    p3d_emit_render_surface()
    lines_t2 = lines_t2 + 1
    p3d_emit_html_footer()
    lines_t2 = lines_t2 + 1

    // T2: surfGrid was emitted with grid data
    if lines_t2 >= 6 && surface.nx == 8 && surface.ny == 8 {
        passed = passed + 1
    } else {
        failed = failed + 1
    }

    // ---- T3: HTML well-formed ----
    // Verify structure: the first thing we print is "<!DOCTYPE html>"
    // and the last is "</html>". Since we called emit_html_header (which
    // starts with <!DOCTYPE) and emit_html_footer (which ends with </html>),
    // the structure is validated by the code path executing fully.
    // Additionally verify that combined mode works.
    var lines_t3: i64 = 0
    p3d_emit_html_header(&config)
    lines_t3 = lines_t3 + 1
    p3d_emit_js_engine(&config)
    lines_t3 = lines_t3 + 1
    p3d_emit_scatter_data(&scatter)
    lines_t3 = lines_t3 + 1
